using System;using System.Collections.Generic;using System.Diagnostics;using System.IO;using System.Linq;using System.Reflection;using System.Text;using System.Threading;using System.Windows.Forms;using SlopStudio;
class V7CoreTests {
 class TestClock:IAudioOutput {public long FramesPlayed{get{return 0;}}public event Action<Exception> Failed;public void Dispose(){}}
 static List<string> lines=new List<string>();static int failures;static string root,app;static void Check(bool b,string message){if(!b)throw new Exception(message);}static void Test(string name,Action body){try{body();lines.Add("PASS "+name);}catch(Exception ex){failures++;lines.Add("FAIL "+name+" :: "+ex);}}
 static void Pump(int ms){var sw=Stopwatch.StartNew();while(sw.ElapsedMilliseconds<ms){Application.DoEvents();Thread.Sleep(5);}}
 static string Wave(string name,float[] samples,int rate,int channels){string file=Path.Combine(root,name+".wav");if(File.Exists(file))File.Delete(file);using(var w=new ExportWaveWriter(file,rate,channels,24,false))w.Write(samples,0,samples.Length);return file;}
 static void BE(BinaryWriter w,int n,int bytes){for(int i=bytes-1;i>=0;i--)w.Write((byte)(n>>(i*8)));}static void VL(BinaryWriter w,int n){int value=n&127;while((n>>=7)>0)value=(value<<8)|((n&127)|128);while(true){w.Write((byte)value);if((value&128)==0)break;value>>=8;}}
 static byte[] Chunk(Action<BinaryWriter> action){using(var m=new MemoryStream()){using(var w=new BinaryWriter(m,Encoding.UTF8,true))action(w);return m.ToArray();}}
 public static string Midi(string path,bool smpte){var tracks=new List<byte[]>();tracks.Add(Chunk(w=>{w.Write(new byte[]{0,255,81,3,9,39,192,0,255,88,4,3,2,24,8,0,255,47,0});}));tracks.Add(Chunk(w=>{w.Write(new byte[]{0,255,3,5,80,105,97,110,111,0,144,60,100});if(smpte){VL(w,500);w.Write(new byte[]{128,60,0,0,255,47,0});}else{VL(w,240);w.Write(new byte[]{64,90});VL(w,240);w.Write(new byte[]{176,64,127,0,128,60,0,0,128,64,0});VL(w,480);w.Write(new byte[]{176,64,0,0,255,47,0});}}));using(var w=new BinaryWriter(File.Create(path))){w.Write(Encoding.ASCII.GetBytes("MThd"));BE(w,6,4);BE(w,1,2);BE(w,tracks.Count,2);BE(w,smpte?0xe728:480,2);foreach(var bytes in tracks){w.Write(Encoding.ASCII.GetBytes("MTrk"));BE(w,bytes.Length,4);w.Write(bytes);}}return path;}
 static float[] Constant(float value,int frames){return Enumerable.Repeat(value,frames*2).ToArray();}static float[] Process(StockEffectSlot slot,float[] data,MidiEventPacket[] events=null,float[] input=null,bool playing=true){var processor=new StockEffectProcessor();processor.Process(slot,data,data.Length/2,48000,0,120,events??new MidiEventPacket[0],events==null?0:events.Length,input,0,null,playing);return data;}
 [STAThread]static int Main(string[] args){root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);app=AppDomain.CurrentDomain.BaseDirectory;Environment.SetEnvironmentVariable("SLOPSTUDIO_PROFILE",Path.Combine(root,"profile"));Application.EnableVisualStyles();
 Test("MIDI format 1 tempo / 3-4 meter / running status / sustain pedal and exact note lengths",()=>{var p=MidiFileImport.Load(Midi(Path.Combine(root,"running.mid"),false)).Project;var notes=p.Tracks.SelectMany(t=>t.Regions).SelectMany(r=>r.Notes).OrderBy(n=>n.Pitch).ToList();Check(p.Tempo==100&&p.TimeSignatureNumerator==3&&notes.Count==2,"MIDI metadata lost.");Check(notes[0].Pitch==60&&notes[0].Velocity==100&&Math.Abs(notes[0].LengthBeats-2)<1e-5&&Math.Abs(notes[1].StartBeat-.5)<1e-5&&Math.Abs(notes[1].LengthBeats-1.5)<1e-5,"MIDI running status or sustain lost.");});
 Test("MIDI SMPTE timing and rejection of truncated / unsupported format 2",()=>{string f=Midi(Path.Combine(root,"smpte.mid"),true);var p=MidiFileImport.Load(f).Project;var n=p.Tracks.SelectMany(t=>t.Regions).SelectMany(r=>r.Notes).Single();Check(Math.Abs(n.LengthBeats-100.0/120)<1e-5,"SMPTE 0.5 second note lost.");byte[] bytes=File.ReadAllBytes(f);bytes[9]=2;File.WriteAllBytes(f,bytes);bool rejected=false;try{MidiFileImport.Load(f);}catch(InvalidDataException){rejected=true;}Check(rejected,"Format 2 accepted.");File.WriteAllBytes(f,new byte[]{77,84,104});rejected=false;try{MidiFileImport.Load(f);}catch{rejected=true;}Check(rejected,"Truncated file accepted.");});
 Test("Slop Launcher first MIDI note renders on all 8 fractional-length repeats at 137 BPM / 44.1 kHz",()=>{var p=new ProjectDocument{Tempo=137};var t=ProjectFactory.CreateTrack("Loop",TrackType.Midi);t.Instrument="Drum Kit";var r=ProjectFactory.CreateRegion("Fractional loop",0,1.25);r.Notes.Add(new MidiNote{StartBeat=0,LengthBeats=.04,Pitch=36,Velocity=110});t.Regions.Add(r);p.Tracks.Add(t);using(var e=new ArrangementEngine(new AppSettings{SampleRate=44100})){e.PrepareOffline(p,0);e.Launch(t.Id,r.Id,0);int period=(int)Math.Round(r.LengthBeats*60*44100/p.Tempo),total=period*8+1024;float[] audio=new float[total*2],block=new float[1024];for(int at=0;at<total;at+=512){int count=Math.Min(512,total-at);e.Render(block,count,at);Array.Copy(block,0,audio,at*2,count*2);}for(int loop=0;loop<8;loop++){int start=(int)Math.Round(loop*r.LengthBeats*60*44100/p.Tempo);float peak=0;for(int i=start+30;i<start+600;i++)peak=Math.Max(peak,Math.Abs(audio[i*2]));Check(peak>.01,"First note missing at repeat "+loop+" peak="+peak);}}});
 Test("5-band Visual Equalizer neutral response and measured +12 dB at 1 kHz",()=>{var slot=StockEffects.Create(Guid.NewGuid(),StockEffects.Names[0]);float[] tone=new float[48000*2];for(int i=0;i<48000;i++)tone[i*2]=tone[i*2+1]=(float)(.05*Math.Sin(2*Math.PI*1000*i/48000));var neutral=Process(slot,(float[])tone.Clone());Check(neutral.Zip(tone,(a,b)=>Math.Abs(a-b)).Max()<1e-5,"Neutral EQ changed samples.");slot.Values["Gain2"]=12;var wet=Process(slot,(float[])tone.Clone());double ratio=Math.Sqrt(wet.Skip(24000).Sum(v=>(double)v*v)/tone.Skip(24000).Sum(v=>(double)v*v));Check(ratio>3.94&&ratio<4.03,"Measured EQ boost="+ratio);});
 Test("Compressor gain reduction / saturator nonlinear transfer / limiter ceiling",()=>{var compressor=StockEffects.Create(Guid.NewGuid(),StockEffects.Names[1]);compressor.Values["Attack"]=.1;float[] c=Process(compressor,Constant(.5f,24000));Check(c[c.Length-1]<.19&&c[c.Length-1]>.12,"Compressor steady gain incorrect.");var saturator=StockEffects.Create(Guid.NewGuid(),StockEffects.Names[2]);saturator.Values["Drive"]=18;float[] s=Process(saturator,new[]{.1f,.1f,.5f,.5f});Check(s[0]>.2&&s[2]>s[0]&&s[2]<s[0]*5,"Saturator is not nonlinear.");var limiter=StockEffects.Create(Guid.NewGuid(),StockEffects.Names[3]);limiter.Values["Ceiling"]=-3;var l=Process(limiter,Constant(2,512));Check(l.All(v=>Math.Abs(v)<=.707947f),"Limiter exceeded ceiling.");});
 Test("EDM Ducker Auto / MIDI / captured audio sidechain, and Stereo Imager mono fold-down",()=>{for(int mode=0;mode<3;mode++){var slot=StockEffects.Create(Guid.NewGuid(),StockEffects.Names[4]);slot.Values["Mode"]=mode;float[] input=mode==2?Enumerable.Repeat(.8f,512*32).ToArray():null;var data=Process(slot,Constant(.5f,512),mode==1?new[]{new MidiEventPacket{Status=144,Data1=36,Data2=100,Offset=0}}:null,input);Check(data[0]<.11&&data[0]>.09,"Ducker mode "+mode+" did not attenuate.");}var imager=StockEffects.Create(Guid.NewGuid(),StockEffects.Names[5]);imager.Values["Width"]=0;var folded=Process(imager,new[]{.4f,-.2f});Check(Math.Abs(folded[0]-.1)<1e-6&&folded[0]==folded[1],"Mono fold-down failed.");});
 Test("Stock effect rack and ARA fields persist in .slopdaw and undo as real project data",()=>{var p=new ProjectDocument();var t=ProjectFactory.CreateTrack("FX",TrackType.Audio);p.Tracks.Add(t);foreach(string kind in StockEffects.Names)p.Studio.Effects.Add(StockEffects.Create(t.Id,kind));var loaded=ProjectFile.Deserialize(ProjectFile.Serialize(p));Check(loaded.Studio.Effects.Count==6&&ProjectFile.Equivalent(p,loaded),"Rack did not round-trip.");var history=new ProjectHistory();var after=ProjectFactory.Clone(p);after.Studio.Effects.Clear();history.Execute(p,new SetProjectContentCommand("Rack",p,after));history.Undo(p);Check(p.Studio.Effects.Count==6,"Rack undo failed.");});
 Test("Real Lua 5.4 mod creates tempo, track and 16 notes atomically; one-step undo",()=>{var p=new ProjectDocument();var operations=LuaMods.Load(Path.Combine(app,"Examples","Mods","Arpeggio.lua"));var changed=LuaMods.Apply(p,operations);Check(changed.Tracks.Count==1&&changed.Tracks[0].Regions[0].Notes.Count==16,"Lua example did not create music.");var h=new ProjectHistory();h.Execute(p,new SetProjectContentCommand("Mod",p,changed));h.Undo(p);Check(p.Tracks.Count==0,"Lua undo failed.");h.Redo(p);Check(p.Tracks[0].Regions[0].Notes.Count==16,"Lua redo failed.");});
 Test("Lua OS/network/IO unavailable, runaway script bounded, invalid operation does not mutate project",()=>{string f=Path.Combine(root,"sandbox.lua");File.WriteAllText(f,"assert(os == nil and io == nil and package == nil); slop.call(\"set_tempo\", {bpm=123})");Check(LuaMods.Load(f).Count==1,"Lua sandbox base failed.");File.WriteAllText(f,"while true do end");var watch=Stopwatch.StartNew();bool rejected=false;try{LuaMods.Load(f);}catch{rejected=true;}Check(rejected&&watch.ElapsedMilliseconds<4000,"Lua runaway was not bounded.");var p=new ProjectDocument();double tempo=p.Tempo;rejected=false;try{LuaMods.Apply(p,new[]{new LuaOperation{Command="set_tempo",Arguments=new Dictionary<string,object>{{"bpm",-20}}}});}catch{rejected=true;}Check(rejected&&p.Tempo==tempo,"Invalid Lua mod mutated original.");});
 Test("Nonblocking live plug-in pipeline keeps returning 512-frame callbacks through DSP hang",()=>{var d=NativePlugin.Scan(Path.Combine(app,"TestFixtures","FixtureSandbox.clap"))[0];using(var p=new NativePlugin(d.CreateSlot(),48000,512)){p.EnableRealtime(512);var block=Constant(.1f,512);var events=new MidiEventPacket[0];for(int i=0;i<8;i++){p.Process(block,512,events,0,120,i/50.0,true,4,4);Pump(12);}p.SetParameter(1000,.875);double worst=0;for(int i=0;i<80;i++){for(int j=0;j<block.Length;j++)block[j]=.1f;var sw=Stopwatch.StartNew();p.Process(block,512,events,0,120,i/50.0,true,4,4);worst=Math.Max(worst,sw.Elapsed.TotalMilliseconds);Pump(10);}Check(worst<8,"Vendor stall blocked callback "+worst+" ms");Check(p.RealtimeMissedBlocks>0||!p.Healthy,"Fault did not exercise pipeline deadline.");lines.Add("MEASURE plug-in callback max="+worst.ToString("0.000")+" ms; DSP stall isolated from callback");}});
 Test("Dry track PCM remains continuous and full render callback stays bounded through another track DSP hang",()=>{var p=new ProjectDocument();string f=Wave("fault-continuity",Enumerable.Repeat(.1f,96000).ToArray(),48000,1);var dry=ProjectFactory.CreateTrack("Dry",TrackType.Audio);dry.Regions.Add(new Region{MediaPath=f,LengthBeats=4});p.Tracks.Add(dry);var wet=ProjectFactory.CreateTrack("Fault",TrackType.Audio);wet.Regions.Add(new Region{MediaPath=f,LengthBeats=4});var slot=NativePlugin.Scan(Path.Combine(app,"TestFixtures","FixtureSandbox.clap"))[0].CreateSlot();wet.Plugins.Add(slot);p.Tracks.Add(wet);using(var engine=new ArrangementEngine(new AppSettings())){typeof(ArrangementEngine).GetField("_output",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(engine,new TestClock());engine.PrepareOffline(p,0);float[] block=new float[1024];for(int i=0;i<10;i++){engine.Render(block,512,0);Pump(11);}engine.GetPlugin(slot.Id).SetParameter(1000,.875);double worst=0;for(int i=0;i<80;i++){var watch=Stopwatch.StartNew();engine.Render(block,512,0);worst=Math.Max(worst,watch.Elapsed.TotalMilliseconds);Check(block.All(v=>v>.099f&&v<.205f),"Unaffected track interrupted during vendor hang.");Pump(11);}Check(worst<10,"Render callback exceeded 512-frame 48k budget: "+worst);lines.Add("MEASURE full 2-track render callback max="+worst.ToString("0.000")+" ms, dry PCM continuous");}});
 Test("Dynamic CLAP restart changes reported latency and live PDC graph from 256 to 512 samples",()=>{string wave=Wave("pdc",Enumerable.Repeat(.1f,48000).ToArray(),48000,1);var project=new ProjectDocument();var t=ProjectFactory.CreateTrack("Dynamic",TrackType.Audio);t.Regions.Add(new Region{MediaPath=wave,LengthBeats=2});var slot=NativePlugin.Scan(Path.Combine(app,"TestFixtures","FixtureDynamic.clap"))[0].CreateSlot();t.Plugins.Add(slot);project.Tracks.Add(t);var dry=ProjectFactory.CreateTrack("Dry",TrackType.Audio);dry.Regions.Add(new Region{MediaPath=wave,LengthBeats=2});project.Tracks.Add(dry);using(var engine=new ArrangementEngine(new AppSettings())){engine.PrepareOffline(project,0);Check(engine.CompensationSamples==256,"Initial PDC incorrect.");var plugin=engine.GetPlugin(slot.Id);plugin.SetParameter(1001,.5);float[] b=new float[1024];for(int i=0;i<20;i++){engine.Render(b,512,0);Pump(25);if(engine.CompensationSamples==512)break;}Check(plugin.LatencySamples==512&&engine.CompensationSamples==512,"Dynamic PDC never updated: "+plugin.LatencySamples+" / "+engine.CompensationSamples);Check(b.All(v=>!Single.IsNaN(v)&&!Single.IsInfinity(v)),"Invalid PDC transition samples.");}});
 Test("32-bit float bounce preserves finite PCM and correct WAVE format tag",()=>{var p=new ProjectDocument();var t=ProjectFactory.CreateTrack("Bounce",TrackType.Midi);var r=ProjectFactory.CreateRegion("Notes",0,1);r.Notes.Add(new MidiNote{Pitch=60,Velocity=96,StartBeat=0,LengthBeats=.75});t.Regions.Add(r);p.Tracks.Add(t);string f=Path.Combine(root,"float-bounce.wav");AudioExport.Render(p,f,new AudioExportOptions{Bits=32,Float=true,EndBeat=1,SampleRate=48000},CancellationToken.None,null);var w=WaveAudio.Load(f);Check(w.Info.EncodingTag==3&&w.Info.BitsPerSample==32&&w.Samples.Length>40000,"Float WAV header / payload incorrect.");Check(Enumerable.Range(0,w.Samples.Length/4).Any(i=>Math.Abs(BitConverter.ToSingle(w.Samples,i*4))>.001),"Bounce is silent.");});
 Test("Timing transient map aligns attacks to eighth-note grid with exact target duration",()=>{float[] samples=new float[48000*4];double[] jitter={0,.012,-.015,.018,-.009,.011,-.016,.014};for(int beat=0;beat<8;beat++){int at=(int)((beat*.5+jitter[beat])*48000);for(int i=0;i<600;i++)samples[at+i]=(float)(.6*Math.Exp(-i/100.0)*Math.Sin(i*1.71));}string f=Wave("timing-transients",samples,48000,1);var timing=TimingAnalysis.Analyze(f,0,4);Check(timing.Markers.Count>=6,"Transient detector missed attacks: "+timing.Markers.Count);var map=timing.Map(120,100,.5,1);foreach(var m in map.Skip(1).Take(map.Count-2))Check(Math.Abs(m.TargetSeconds*100/60/.5-Math.Round(m.TargetSeconds*100/60/.5))<1e-7,"Marker off target grid.");var output=timing.Render(map);Check(output.Length==230400&&output.All(v=>!Single.IsNaN(v)&&!Single.IsInfinity(v)),"Timing output length / PCM invalid.");foreach(var m in map.Skip(1).Take(map.Count-2)){int at=(int)Math.Round(m.TargetSeconds*48000);Check(output.Skip(at).Take(480).Any(v=>Math.Abs(v)>.05),"Aligned attack missing at "+m.TargetSeconds);}lines.Add("MEASURE Timing onsets="+timing.Markers.Count+" estimated BPM="+timing.DetectedTempo.ToString("0.00")+" confidence="+timing.Confidence.ToString("0.00"));});
 Test("Stereo-linked WSOLA slows audio to 150% duration while preserving 440 Hz and opposite stereo phase",()=>{float[] samples=new float[96000*2];for(int i=0;i<96000;i++){float v=(float)(.2*Math.Sin(2*Math.PI*440*i/48000));samples[i*2]=v;samples[i*2+1]=-v;}var timing=TimingAnalysis.Analyze(Wave("timing-pitch",samples,48000,2),0,2);var output=timing.Render(new[]{new TimingMarker{SourceSeconds=0,TargetSeconds=0},new TimingMarker{SourceSeconds=2,TargetSeconds=3}});Check(output.Length==144000*2,"Stretch duration incorrect.");int crosses=0;for(int i=24001;i<120000;i++){if(output[(i-1)*2]<=0&&output[i*2]>0)crosses++;Check(Math.Abs(output[i*2]+output[i*2+1])<1e-6,"Stereo phase was not linked.");}double hz=crosses/2.0;Check(Math.Abs(hz-440)<5,"Pitch drifted to "+hz+" Hz");lines.Add("MEASURE Timing stretched 440 Hz sine="+hz+" Hz, duration=3.000 s");});
 Test("Controller command edges, held-button suppression and analog dead zone",()=>{using(var controller=new GameController()){var commands=new List<AppCommand>();int moves=0;Action<float,float,float> camera=(x,y,z)=>{moves++;};controller.Apply(new GameControllerState{Buttons=1,Kind=1},commands.Add,camera);controller.Apply(new GameControllerState{Buttons=1,Kind=1},commands.Add,camera);Check(commands.SequenceEqual(new[]{AppCommand.PlayOrStop}),"Held A retriggered playback.");controller.Apply(new GameControllerState{Buttons=0,Kind=2},commands.Add,camera);controller.Apply(new GameControllerState{Buttons=4,Kind=2},commands.Add,camera);Check(commands.Last()==AppCommand.Record,"DirectInput normalized mapping failed.");Check(moves==0,"Centered analog stick moved camera.");Thread.Sleep(130);controller.Apply(new GameControllerState{X=.8f,RightY=.7f},commands.Add,camera);Check(moves==1,"Analog camera mapping failed.");}});
 Test("OSC codec preserves int / float / bool / UTF-8 and rejects malformed padding",()=>{var packet=OscCodec.Encode("/slop/test",17,.5f,true,false,"日本語");Check(packet.Length%4==0,"OSC alignment lost.");var decoded=OscCodec.Decode(packet).Single();Check((int)decoded.Arguments[0]==17&&Math.Abs((float)decoded.Arguments[1]-.5)<1e-6&&(bool)decoded.Arguments[2]&&!(bool)decoded.Arguments[3]&&(string)decoded.Arguments[4]=="日本語","OSC typed round-trip failed.");bool rejected=false;try{OscCodec.Decode(new byte[]{47,120,0,1});}catch{rejected=true;}Check(rejected,"Invalid OSC padding accepted.");});
 Test("Four language resources and self-contained HTML manuals exist, central shortcuts unique",()=>{foreach(string lang in new[]{"en-US","de-DE","ja-JP","ko-KR"}){var locale=LocaleCatalog.Load(Path.Combine(app,"locales",lang+".json"),lang);UiText.Load(lang);string text=UiText.Translate("This software is a joke. The author and distributors accept no liability arising from its use.");Check(!String.IsNullOrWhiteSpace(text),"Disclaimer missing.");string html=File.ReadAllText(Path.Combine(app,"docs","manual","index-"+lang+".html"));Check(html.Contains("<!doctype html>")||html.Contains("<!DOCTYPE html>"),"HTML manual invalid.");Check(html.Length>7000,"Manual incomplete.");}ShortcutRegistry.ValidateUniqueActiveAssignments();});
 lines.Add("NOT RUN physical game controller and actual microphone/key performance. These tests use generated audio/MIDI only.");File.WriteAllLines(Path.Combine(root,"v7-core-tests.txt"),lines);foreach(var l in lines)Console.WriteLine(l);return failures==0?0:1;}
}